def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if budget <= 0:
        return 0

    if not alive:
        base = DAILY_SALARY * 0.35
        if hp <= 2 or no_water >= 1:
            base = DAILY_SALARY * 0.75
        return max(0, min(budget, base))

    prev_bids = []
    opp_urgent = 0
    opp_errors = 0
    for opp in alive:
        prev = opp.get('previous_trace', {})
        if prev:
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(bid)
            if prev.get('error'):
                opp_errors += 1
        if opp.get('hp', 10) <= 2 or opp.get('no_water_days', 0) >= 1:
            opp_urgent += 1

    high_pressure = 0
    avg_pressure = 0
    if prev_bids:
        high_pressure = max(prev_bids)
        avg_pressure = sum(prev_bids) / float(len(prev_bids))

    supply_ratio = supply / float(WATER_REQ)

    if hp <= 1 or no_water >= 2:
        bid = DAILY_SALARY * 0.98
    elif hp <= 2 or no_water >= 1:
        bid = DAILY_SALARY * 0.88
    else:
        if supply_ratio >= 1.8:
            bid = DAILY_SALARY * 0.34
        elif supply_ratio >= 1.4:
            bid = DAILY_SALARY * 0.46
        else:
            bid = DAILY_SALARY * 0.6

        if high_pressure > 0:
            if high_pressure >= DAILY_SALARY * 0.9:
                bid = max(bid, DAILY_SALARY * 0.52)
            elif high_pressure >= DAILY_SALARY * 0.7:
                bid = max(bid, min(DAILY_SALARY * 0.78, high_pressure + 2.0))
            else:
                bid = max(bid, avg_pressure + 1.5)

        if opp_urgent >= max(1, len(alive) // 2):
            bid += 4.0
        if opp_errors > 0:
            bid -= 2.0

    if budget < DAILY_SALARY * 2 and hp > 2 and no_water == 0:
        bid *= 0.82

    bid = max(0, min(budget, bid))
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = int(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0.0))

    # Collect immediate opponent reaction from yesterday's trace
    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    # Default moderate bid: aim to win when supply is tight, but avoid wasting budget
    # Use supply ratio to scale aggressiveness.
    supply_ratio = 0.0
    if WATER_REQ > 0:
        supply_ratio = supply / float(WATER_REQ)

    # Baseline: bid around 0.45 of daily salary, boosted when supply is low relative to requirement.
    # supply_ratio < 2 means likely scarcity; raise bid.
    if supply_ratio <= 1.8:
        baseline = DAILY_SALARY * 0.65
    elif supply_ratio <= 2.4:
        baseline = DAILY_SALARY * 0.50
    else:
        baseline = DAILY_SALARY * 0.40

    # If yesterday we observed any high bids, respond more aggressively.
    observed_bids = []
    observed_highest = None
    for _, opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                b_val = float(b)
                observed_bids.append(b_val)
            except Exception:
                pass

    if observed_bids:
        observed_highest = max(observed_bids)

    # Health pressure: if we're low hp, we must secure water.
    if hp <= 2:
        health_factor = 0.9
    elif hp <= 3:
        health_factor = 0.75
    else:
        health_factor = 0.6

    # Opponent pressure: if any opponent bid near their daily salary, likely contested.
    # We don't know their salary exactly, but we can compare to our DAILY_SALARY as a proxy.
    if observed_highest is not None:
        if observed_highest >= DAILY_SALARY * 0.85:
            bid = max(baseline, observed_highest + 1.0)
            bid *= 1.05
        elif observed_highest >= DAILY_SALARY * 0.65:
            bid = max(baseline, observed_highest + 0.5)
        else:
            bid = baseline
    else:
        bid = baseline

    bid *= health_factor

    # Budget cap and floor to avoid bidding zero when we need water.
    if budget <= 0:
        return 0.0

    # Ensure we never exceed budget.
    if bid > budget:
        bid = budget

    # If we still have enough budget, avoid extremely tiny bids when supply is scarce.
    # (No-water days not used directly since we only have it in my_status but not required.)
    if supply_ratio <= 1.8 and bid < DAILY_SALARY * 0.25:
        bid = min(budget, DAILY_SALARY * 0.35)

    # Final clamp
    if bid < 0.0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # If no active opponents, bid minimal to save budget
    if not alive_opponents:
        return min(my_status['budget'], 1)

    # Prioritize survival if HP is critically low (1 or 2)
    if my_status['hp'] <= 2:
        return min(my_status['budget'], DAILY_SALARY * 0.95)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        # If previous bids were very high, outbid them to secure water.
        # Given constant tight supply, trying to save when opponents bid high is too risky.
        if highest_prev_bid >= DAILY_SALARY * 0.75: # React aggressively if bids are high
            # Bid slightly higher than the highest previous bid to ensure winning
            return min(my_status['budget'], highest_prev_bid + 5) 

        # If previous bids were moderate, bid slightly above the highest.
        # Ensure a minimum bid to stay competitive.
        return min(my_status['budget'], max(DAILY_SALARY * 0.55, highest_prev_bid + 2))

    else: # No previous bids available (e.g., first day)
        # Start with a strong base bid.
        # Given that supply is always less than demand for 2+ agents, it's always competitive.
        # A higher base bid is safer than a low one.
        return min(my_status['budget'], DAILY_SALARY * 0.65)

